CREATE COLUMN TABLE "TEST_AP"."OFAA" ("Code" INTEGER CS_INT NOT NULL , "Name" NVARCHAR(100) NOT NULL , "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "LogInstanc" INTEGER CS_INT DEFAULT 0, "CreateDate" LONGDATE CS_LONGDATE, "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "Locked" NVARCHAR(1) DEFAULT 'N', "SnapshotId" INTEGER CS_INT DEFAULT 0, PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OFAA_Name" ON "TEST_AP"."OFAA" ( "Name" ASC )